begin;
select plan(47);
insert into auth.users(id,email,raw_user_meta_data) values ('a2929292-0000-0000-0000-000000000001','planning-owner@test.local','{}'),('a2929292-0000-0000-0000-000000000002','planning-editor@test.local','{}'),('a2929292-0000-0000-0000-000000000003','planning-former@test.local','{}');
insert into public.trips(id,name,destination,start_date,end_date,created_by) values ('b2929292-0000-0000-0000-000000000001','Planning trip','Hue','2026-11-27','2026-11-30','a2929292-0000-0000-0000-000000000001');
insert into public.trip_members(trip_id,user_id,role) values ('b2929292-0000-0000-0000-000000000001','a2929292-0000-0000-0000-000000000001','owner'),('b2929292-0000-0000-0000-000000000001','a2929292-0000-0000-0000-000000000002','editor'),('b2929292-0000-0000-0000-000000000001','a2929292-0000-0000-0000-000000000003','editor');
select set_config('request.jwt.claim.sub','a2929292-0000-0000-0000-000000000001',true);
set local role authenticated;
insert into public.itinerary_items(id,trip_id,title,visit_date,end_date,start_time,end_time) values ('c2929292-0000-0000-0000-000000000001','b2929292-0000-0000-0000-000000000001','Camping','2026-11-27','2026-11-29','20:00','08:00'),('c2929292-0000-0000-0000-000000000002','b2929292-0000-0000-0000-000000000001','Cafe','2026-11-28',null,'09:00','10:00');
select public.save_trip_checklist('b2929292-0000-0000-0000-000000000001',null,null,'Pack', 'a2929292-0000-0000-0000-000000000002',true);
select public.save_expense_with_participants('b2929292-0000-0000-0000-000000000001',null,null,'Shared','food','2026-11-27',10000,10000,'a2929292-0000-0000-0000-000000000001',array['a2929292-0000-0000-0000-000000000001'::uuid,'a2929292-0000-0000-0000-000000000002'::uuid],'',null,'equal','{}');
select public.save_expense_with_participants('b2929292-0000-0000-0000-000000000001',null,null,'Frozen','food','2026-11-27',12000,12000,'a2929292-0000-0000-0000-000000000003',array['a2929292-0000-0000-0000-000000000003'::uuid],'',null,'equal','{}');
select public.remove_trip_member('b2929292-0000-0000-0000-000000000001','a2929292-0000-0000-0000-000000000003');
select public.record_settlement_payment('b2929292-0000-0000-0000-000000000001','a2929292-0000-0000-0000-000000000002',1000,0);
create function pg_temp.itin() returns jsonb language sql as $$select coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version)),'[]') from public.itinerary_items where trip_id='b2929292-0000-0000-0000-000000000001'$$;
create function pg_temp.costs() returns jsonb language sql as $$select coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version)),'[]') from public.expenses where trip_id='b2929292-0000-0000-0000-000000000001'$$;
create function pg_temp.tasks() returns jsonb language sql as $$select coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version)),'[]') from public.checklist_items where trip_id='b2929292-0000-0000-0000-000000000001' and deleted_at is null$$;
create function pg_temp.finances() returns jsonb language sql as $$select jsonb_agg(jsonb_build_object('amount',e.actual_amount_vnd,'estimate',e.estimated_amount_vnd,'payer',e.paid_by,'method',e.split_method,'participants',(select jsonb_agg(to_jsonb(p) order by p.user_id) from public.expense_participants p where p.expense_id=e.id)) order by e.id) from public.expenses e where trip_id='b2929292-0000-0000-0000-000000000001'$$;
select set_config('test.money',pg_temp.finances()::text,true);
select set_config('test.payments',(select jsonb_agg(to_jsonb(p) order by id)::text from public.settlement_payments p where trip_id='b2929292-0000-0000-0000-000000000001'),true);
select lives_ok($$select public.delete_trip_itinerary_item('b2929292-0000-0000-0000-000000000001','c2929292-0000-0000-0000-000000000002',1)$$,'single delete uses recoverable trash');
select is((select count(*)::integer from public.itinerary_trash where trip_id='b2929292-0000-0000-0000-000000000001'),1,'owner sees one deleted snapshot');
select ok((select expires_at-deleted_at=interval '7 days' from public.itinerary_trash where id='c2929292-0000-0000-0000-000000000002'),'seven day recovery window');
select ok(not has_table_privilege('authenticated','public.itinerary_items','DELETE'),'old direct DELETE cannot bypass trip locking');
select set_config('request.jwt.claim.sub','a2929292-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from public.itinerary_trash),0,'editor cannot read trash');
select throws_ok($$select public.restore_trip_itinerary_item('b2929292-0000-0000-0000-000000000001','c2929292-0000-0000-0000-000000000002',1,(select deleted_at from public.itinerary_trash where trip_id='b2929292-0000-0000-0000-000000000001' and id='c2929292-0000-0000-0000-000000000002'))$$,'42501',null,'editor cannot restore');
select throws_ok($$select public.reschedule_trip('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'2026-12-04',true,pg_temp.itin(),pg_temp.costs())$$,'42501',null,'editor cannot move trip');
select throws_ok($$select public.clone_trip_template('b2929292-0000-0000-0000-000000000001',1,'Copy','2027-01-01','d2929292-0000-0000-0000-000000000001',pg_temp.itin(),pg_temp.tasks())$$,'42501',null,'editor cannot clone as owner');
select set_config('request.jwt.claim.sub','a2929292-0000-0000-0000-000000000001',true);
select lives_ok($$select public.restore_trip_itinerary_item('b2929292-0000-0000-0000-000000000001','c2929292-0000-0000-0000-000000000002',1,(select deleted_at from public.itinerary_trash where trip_id='b2929292-0000-0000-0000-000000000001' and id='c2929292-0000-0000-0000-000000000002'))$$,'owner restores original item');
select is((select version from public.itinerary_items where id='c2929292-0000-0000-0000-000000000002'),2,'restored item has new version');
select throws_ok($$select public.delete_trip_itinerary_item('b2929292-0000-0000-0000-000000000001','c2929292-0000-0000-0000-000000000002',1)$$,'40001',null,'stale client cannot delete restored row');
select public.delete_trip_itinerary_item('b2929292-0000-0000-0000-000000000001','c2929292-0000-0000-0000-000000000002',2);
select throws_ok($$select public.reschedule_trip('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'2026-12-04',false,pg_temp.itin(),pg_temp.costs())$$,'23514',null,'preserved out-of-range expense dates block reschedule');
select is((select start_date from public.trips where id='b2929292-0000-0000-0000-000000000001'),'2026-11-27'::date,'failed reschedule retains trip dates');
select throws_ok($$select public.reschedule_trip('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'2026-12-04',true,'[]',pg_temp.costs())$$,'40001',null,'added or missing itinerary snapshot rejected');
select throws_ok($$select public.reschedule_trip('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'2026-12-04',true,pg_temp.itin(),'[]')$$,'40001',null,'expense snapshot mismatch rejected');
select throws_ok($$select public.reschedule_trip('b2929292-0000-0000-0000-000000000001',0,'2026-12-04',true,pg_temp.itin(),pg_temp.costs())$$,'40001',null,'stale trip rejected');
select throws_ok($$select public.reschedule_trip('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'2026-11-27',true,pg_temp.itin(),pg_temp.costs())$$,'22023',null,'no-op move rejected');
select lives_ok($$select public.reschedule_trip('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'2026-12-04',true,pg_temp.itin(),pg_temp.costs())$$,'owner moves trip and expenses atomically');
select is((select end_date from public.trips where id='b2929292-0000-0000-0000-000000000001'),'2026-12-07'::date,'trip duration retained');
select is((select end_date from public.itinerary_items where id='c2929292-0000-0000-0000-000000000001'),'2026-12-06'::date,'multi-day endpoint shifts');
select is((select start_time::text||'/'||end_time::text from public.itinerary_items where id='c2929292-0000-0000-0000-000000000001'),'20:00:00/08:00:00','activity times unchanged');
select is((select min(expense_date) from public.expenses where trip_id='b2929292-0000-0000-0000-000000000001'),'2026-12-04'::date,'expense dates shift explicitly');
select is(pg_temp.finances(),current_setting('test.money')::jsonb,'all money and former-member splits unchanged');
select is((select jsonb_agg(to_jsonb(p) order by id) from public.settlement_payments p where trip_id='b2929292-0000-0000-0000-000000000001'),current_setting('test.payments')::jsonb,'settlement payments untouched');
select throws_ok($$select public.restore_trip_itinerary_item('b2929292-0000-0000-0000-000000000001','c2929292-0000-0000-0000-000000000002',2,(select deleted_at from public.itinerary_trash where trip_id='b2929292-0000-0000-0000-000000000001' and id='c2929292-0000-0000-0000-000000000002'))$$,'23514',null,'restore outside moved trip dates rejected');
select is((select count(*)::integer from public.itinerary_trash where id='c2929292-0000-0000-0000-000000000002'),1,'failed restore retains snapshot');
select set_config('test.clone_id',public.clone_trip_template('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'New copy','2027-01-10','d2929292-0000-0000-0000-000000000001',pg_temp.itin(),pg_temp.tasks())::text,true);
select is((select count(*)::integer from public.itinerary_items where trip_id=current_setting('test.clone_id')::uuid),1,'clone copies active itinerary only');
select is((select visit_date from public.itinerary_items where trip_id=current_setting('test.clone_id')::uuid),'2027-01-10'::date,'clone dates shifted');
select is((select count(*)::integer from public.trip_members where trip_id=current_setting('test.clone_id')::uuid),1,'clone has only its owner');
select is((select count(*)::integer from public.trip_invitations where trip_id=current_setting('test.clone_id')::uuid),0,'no invitation acceptance copied');
select is((select count(*)::integer from public.expenses where trip_id=current_setting('test.clone_id')::uuid),0,'no financial rows copied');
select is((select count(*)::integer from public.settlement_payments where trip_id=current_setting('test.clone_id')::uuid),0,'no payments copied');
select ok((select not completed and assigned_to is null and title='Pack' from public.checklist_items where trip_id=current_setting('test.clone_id')::uuid),'checklist reset for new trip');
select is(public.clone_trip_template('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'New copy','2027-01-10','d2929292-0000-0000-0000-000000000001',pg_temp.itin(),pg_temp.tasks())::text,current_setting('test.clone_id'),'clone retry returns original trip');
select is((select count(*)::integer from public.itinerary_items where trip_id=current_setting('test.clone_id')::uuid),1,'clone retry does not duplicate content');
select throws_ok($$select public.clone_trip_template('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'Changed request','2027-01-11','d2929292-0000-0000-0000-000000000001',pg_temp.itin(),pg_temp.tasks())$$,'22023',null,'reused key with different dates denied');
select throws_ok($$select public.clone_trip_template('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'Stale','2027-02-01','d2929292-0000-0000-0000-000000000002','[]',pg_temp.tasks())$$,'40001',null,'stale source snapshot blocks clone');
reset role;
update public.itinerary_trash set expires_at=now()-interval '1 second' where id='c2929292-0000-0000-0000-000000000002';
set local role authenticated;
select is((select count(*)::integer from public.itinerary_trash),0,'expired snapshots hidden');
select throws_ok($$select public.restore_trip_itinerary_item('b2929292-0000-0000-0000-000000000001','c2929292-0000-0000-0000-000000000002',2,(select deleted_at from public.itinerary_trash where trip_id='b2929292-0000-0000-0000-000000000001' and id='c2929292-0000-0000-0000-000000000002'))$$,'40001',null,'expired restore rejected');
reset role;
select is(private.purge_expired_itinerary_trash(),1,'cleanup removes expired row');
set local role authenticated;
select ok(not has_function_privilege('anon','public.reschedule_trip(uuid,integer,date,boolean,jsonb,jsonb)','execute'),'anonymous cannot reschedule');
select ok(not has_function_privilege('anon','public.clone_trip_template(uuid,integer,text,date,uuid,jsonb,jsonb)','execute'),'anonymous cannot clone');
select ok(not has_function_privilege('authenticated','private.purge_expired_itinerary_trash()','execute'),'client cannot run global purge');
select throws_ok($$select public.clone_trip_template('b2929292-0000-0000-0000-000000000001',(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'),'Different name','2027-01-10','d2929292-0000-0000-0000-000000000001',pg_temp.itin(),pg_temp.tasks())$$,'22023',null,'retry key also binds clone name');
select public.set_trip_archived('b2929292-0000-0000-0000-000000000001',true,(select version from public.trips where id='b2929292-0000-0000-0000-000000000001'));
select throws_ok($$select public.reschedule_trip('b2929292-0000-0000-0000-000000000001',1,'2027-02-01',true,'[]','[]')$$,'42501',null,'archived trip cannot reschedule');
select throws_ok($$select public.clone_trip_template('b2929292-0000-0000-0000-000000000001',1,'Archived copy','2027-02-01','d2929292-0000-0000-0000-000000000003','[]','[]')$$,'42501',null,'archived source cannot clone');
select throws_ok($$select public.restore_trip_itinerary_item('b2929292-0000-0000-0000-000000000001','c2929292-0000-0000-0000-000000000002',2,(select deleted_at from public.itinerary_trash where trip_id='b2929292-0000-0000-0000-000000000001' and id='c2929292-0000-0000-0000-000000000002'))$$,'42501',null,'archived trash cannot restore');
select * from finish();
rollback;
